function refineStory(id, btn) {
  // Optional free-form guidance for the refine agent. Blank runs the default
  // pass; Cancel aborts entirely (null), an empty string proceeds with no note.
  const note = prompt('Instructions for the refine agent (optional — leave blank for the default pass):', '');
  if (note === null) return;
  btn.disabled = true;
  const orig = btn.textContent;
  btn.textContent = 'spawning…';
  fetch('/spawnloop/refine', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({id: id, note: note})
  })
    .then(r => r.ok ? r.json() : r.text().then(t => Promise.reject(t)))
    .then(d => { btn.textContent = 'spawned ' + (d.pane || ''); })
    .catch(e => { btn.disabled = false; btn.textContent = orig; alert('refine failed: ' + e); });
}

